function useHashRoute(){
  const initial=location.hash.slice(1)||'/operations/visits';
  const [route,setRouteState]=useState(initial);
  React.useEffect(()=>{ const fn=()=>setRouteState(location.hash.slice(1)||'/operations/visits'); addEventListener('hashchange',fn); return()=>removeEventListener('hashchange',fn)},[]);
  const go=(path)=>{ location.hash=path; setRouteState(path); window.scrollTo({top:0,behavior:'smooth'}); };
  return [route,go];
}

const cls=(...v)=>v.filter(Boolean).join(' ');
const Icon=({name})=><span className="icon" aria-hidden="true">{{calendar:'▣',user:'●',clock:'◷',alert:'!',safe:'◆',doc:'▤',check:'✓',spark:'✦',home:'⌂',search:'⌕',chev:'›',close:'×',plus:'＋',arrow:'→'}[name]||'•'}</span>;

function Badge({tone='neutral',children}){ return <span className={`badge ${tone}`}><span className="badge-dot"/>{children}</span> }
function Button({children,tone='default',onClick,type='button'}){ return <button type={type} className={`button ${tone}`} onClick={onClick}>{children}</button> }
function LanguageSelector(){
  const {language,setLanguage,languages}=useI18n();
  const [open,setOpen]=useState(false);
  const pickerRef=React.useRef(null);
  const current=languages.find(option=>option.value===language)||languages[0];
  React.useEffect(()=>{
    if(!open)return undefined;
    const close=event=>{if(!pickerRef.current?.contains(event.target))setOpen(false)};
    const escape=event=>{if(event.key==='Escape')setOpen(false)};
    document.addEventListener('pointerdown',close);
    document.addEventListener('keydown',escape);
    return()=>{document.removeEventListener('pointerdown',close);document.removeEventListener('keydown',escape)};
  },[open]);
  return <div className="language-picker" ref={pickerRef} data-i18n-ignore>
    <button className="language-trigger" type="button" aria-label="Language" aria-haspopup="menu" aria-expanded={open} onClick={()=>setOpen(value=>!value)}><span className="language-flag" aria-hidden="true">{current.flag}</span><span>Language</span><b>{current.shortLabel}</b><span className="language-chevron" aria-hidden="true">⌄</span></button>
    {open&&<div className="language-menu" role="menu">{languages.map(option=><button type="button" role="menuitemradio" aria-checked={option.value===language} className={option.value===language?'active':''} key={option.value} onClick={()=>{setLanguage(option.value);setOpen(false)}}><span><span className="language-flag" aria-hidden="true">{option.flag}</span>{option.label}</span><small>{option.shortLabel}</small></button>)}</div>}
  </div>
}
function Card({children,className='',onClick}){ return <section className={cls('card',onClick&&'clickable',className)} onClick={onClick}>{children}</section> }
function SectionTitle({title,desc,action}){ return <div className="section-title"><div><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>{action&&<div className="section-actions">{action}</div>}</div> }
function Metric({label,value,desc,tone='teal',icon}){ return <div className="metric"><span className={`metric-icon ${tone}`}><Icon name={icon||'doc'}/></span><div><small>{label}</small><strong>{value}</strong><span>{desc}</span></div></div> }
function MetricStrip({items,className=''}){ return <Card className={cls('metric-strip',className)}>{items.map((x,i)=><Metric key={i}{...x}/>)}</Card> }
function Progress({value,tone='teal'}){ return <div className="progress"><span className={tone} style={{width:`${value}%`}}/></div> }
function Donut({value=67,label='오늘 방문',main='28/42'}){ return <div className="donut-stat"><strong className="donut-title">{label}</strong><div className="donut" style={{'--v':`${value*3.6}deg`}}><div><strong>{main}</strong><span>{value}% 완료</span></div></div></div> }
function Search({value,onChange,placeholder='이름을 검색하세요'}){return <label className="search"><Icon name="search"/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>}
function Select({children}){ return <select defaultValue="all"><option value="all">{children}</option><option>확인 필요</option><option>진행 중</option><option>완료</option></select> }
function Filters({search,setSearch,extra=true}){ return <Card className="filters"><label><span>기준일</span><input type="date" defaultValue="2026-09-22"/></label>{extra&&<><label><span>전체 상태</span><Select>전체</Select></label><label><span>담당 직원</span><Select>전체</Select></label><label><span>제공 서비스</span><Select>전체</Select></label></>}{setSearch&&<label className="filter-search"><span>검색</span><Search value={search} onChange={setSearch}/></label>}<Button>초기화</Button></Card> }

function Modal({modal,onClose}){ if(!modal)return null; return <div className="overlay" onMouseDown={onClose}><div className="modal" role="dialog" aria-modal="true" onMouseDown={e=>e.stopPropagation()}><header><div><Badge tone={modal.tone||'teal'}>{modal.tag||'상세 정보'}</Badge><h2>{modal.title}</h2></div><div className="modal-header-actions">{modal.headerAction&&<Button tone="primary" onClick={modal.onHeaderAction||onClose}>{modal.headerAction}</Button>}<button className="close" onClick={onClose}><Icon name="close"/></button></div></header><div className="modal-body">{modal.body||<><div className="detail-grid"><div><small>담당자</small><strong>이○○ 사회복지사</strong></div><div><small>처리 기한</small><strong>2026.09.25</strong></div><div><small>상태</small><strong>확인 필요</strong></div></div><Card className="soft"><h3>확인 내용</h3><p>관련 기록과 최근 변화가 함께 표시됩니다. 담당자가 원본 기록을 확인한 뒤 다음 행동을 결정할 수 있습니다.</p></Card></>}</div><footer><Button onClick={onClose}>닫기</Button>{!modal.hideConfirm&&<Button tone="primary" onClick={onClose}>{modal.confirmLabel||'확인 완료'}</Button>}</footer></div></div> }

function Sidebar({route,go}){
  return <aside className="sidebar"><div className="brand"><div className="logo">♥</div><strong>케어로그</strong></div><p className="org">방문요양 · ○○재가센터</p><nav>{NAV.map(group=>{const active=route.startsWith('/'+group.key);return <div className="nav-group" key={group.key}><div className={cls('nav-depth1',active&&'active')}><span className="nav-dot"/>{group.label}<span>⌃</span></div><div className="nav-depth2">{group.items.map(([path,label,nested],i)=>{const selected=route===path && (label!=='돌봄 기록'||route==='/care/records/daily');return <button className={cls(nested&&'nested',selected&&'selected')} key={label+i} onClick={()=>go(path)}>{label}</button>})}</div></div>})}</nav><div className="account"><div className="avatar">이</div><div><strong>이○○ 관리자</strong><button>로그아웃</button></div></div></aside>
}

function Layout({route,go,children}){ const info=pageInfo[route]||['케어로그','']; const feedback=route==='/improvement/feedback'; const staffOverview=route==='/staff/overview'; const monthly=route==='/care/records/monthly'; return <div className="app"><Sidebar route={route} go={go}/><main><header className="topbar"><div><h1>{info[0]}</h1><p>{info[1]}</p></div><div className="top-actions"><LanguageSelector/><div className="date-actions">{staffOverview?<div className="staff-top-actions"><span>기준일 2026.09.28</span></div>:monthly?<div className="updated-at"><strong>기준일 2026.09.30</strong><span>업데이트 10:35</span></div>:<><span>{!feedback&&<Icon name="calendar"/>}{feedback?'2026년 9월 22일':'기준일 2026.09.22'}</span>{!feedback&&<><Button>오늘</Button><Button>‹</Button><Button>›</Button></>}</>}</div></div></header><div className="top-divider"/>{children}</main></div> }

