function VisitDetail({visit,open}){ return <div className="expanded"><div className="expanded-head"><div><h3>{visit.recipient} 어르신 · {visit.time} · 방문 서비스 상세</h3><p>계획된 서비스와 실제 수행 내용을 함께 확인합니다.</p></div><Button onClick={()=>open('돌봄 기록 원본',{tag:'원본 기록'})}>돌봄 기록 보기 <Icon name="chev"/></Button></div><div className="service-lines"><p><Badge tone="teal">신체활동 4</Badge><span>세면 · 목욕 · 이동 · 옷 갈아입기</span></p><p><Badge tone="blue">인지·정서 2</Badge><span>말벗 · 불안 완화</span></p><p><Badge tone="neutral">가사·일상 2</Badge><span>세탁 · 주변 정돈</span></p></div><div className="note-grid"><div className="note warning"><Icon name="alert"/><div><strong>확인 사항</strong><p>목욕 시작 전 거부 의사를 표현했으나 물 온도를 직접 확인하도록 지원하자 참여했습니다.</p></div></div><div className="note teal"><Icon name="spark"/><div><strong>다음 방문 참고</strong><p>물 온도 확인과 서비스 순서 설명을 유지하고 반복 시 개인별 계획 반영을 검토합니다.</p></div></div></div></div> }

function OperationsVisits({open}){const [selected,setSelected]=useState(1);return <Page><div className="overview-row"><Card className="visit-donut"><Donut/></Card><MetricStrip items={[{label:'지연',value:'2건',desc:'방문 기준',tone:'red',icon:'clock'},{label:'미방문',value:'1건',desc:'방문 기준',tone:'orange',icon:'alert'},{label:'안전 신호',value:'1건',desc:'방문 기준',tone:'green',icon:'safe'},{label:'이탈 근무',value:'1명',desc:'직원 기준',tone:'blue',icon:'user'},{label:'확인 필요',value:'4명',desc:'직원 기준',tone:'gray',icon:'doc'}]}/></div><div className="subtabs"><button className="active">방문 현황</button><button onClick={()=>location.hash='/operations/staff'}>직원 활동</button></div><Filters/><Card className="table-card"><SectionTitle title="방문 일정표" action={<strong className="teal-text">총 5건</strong>}/><div className="table visit-table"><div className="tr th"><span>서비스 시간</span><span>수급자</span><span>담당</span><span>제공 서비스</span><span>방문 상태</span><span>기록</span><span>확인 사항</span><span/></div>{visits.map((v,i)=><React.Fragment key={v.time}><button className={cls('tr',selected===i&&'row-selected')} onClick={()=>setSelected(selected===i?null:i)}><span>{v.time}</span><strong>{v.recipient}</strong><span>{v.staff}</span><span className="service-text">{v.services.split(' · ').map((part,index,parts)=><React.Fragment key={part}>{part}{index<parts.length-1&&<> · <wbr/></>}</React.Fragment>)}</span><Badge tone={v.tone}>{v.status}</Badge><span>{v.record}</span><span>{v.note}</span><Icon name="chev"/></button>{selected===i&&<VisitDetail visit={v} open={(title,opts)=>open({title,...opts})}/>}</React.Fragment>)}</div></Card></Page>}

