  {staff:'김○○',scheduledIn:'09:00',actualIn:'08:52',scheduledOut:'18:00',actualOut:'18:04',hours:'9시간 12분',status:'정상',tone:'success',service:'방문요양'},
  {staff:'박○○',scheduledIn:'09:00',actualIn:'09:14',scheduledOut:'18:00',actualOut:'18:02',hours:'8시간 48분',status:'지각',tone:'warning',service:'방문요양'},
  {staff:'이○○',scheduledIn:'09:00',actualIn:'—',scheduledOut:'18:00',actualOut:'—',hours:'—',status:'출근 누락',tone:'danger',service:'행정지원'},
  {staff:'최○○',scheduledIn:'09:00',actualIn:'08:57',scheduledOut:'18:00',actualOut:'17:10',hours:'8시간 13분',status:'조퇴',tone:'blue',service:'방문요양'}
