function Attendance({open}){
  const[date,setDate]=useState('2026-09-22');
  const[status,setStatus]=useState('all');
  const[staff,setStaff]=useState('all');
  const[service,setService]=useState('all');
  const filtered=attendanceRows.filter(row=>(status==='all'||row.status===status)&&(staff==='all'||row.staff===staff)&&(service==='all'||row.service===service));
  const reset=()=>{setDate('2026-09-22');setStatus('all');setStaff('all');setService('all')};
  return <Page><MetricStrip items={[{label:'근태 정상률',value:'96.2%',desc:'최근 3개월'},{label:'근태 이상',value:'3건',desc:'지각 2 · 누락 1',tone:'orange'},{label:'휴가 예정',value:'2명',desc:'이번 주',tone:'blue'},{label:'수정 요청',value:'1건',desc:'관리자 승인',tone:'red'}]}/><Card className="filters"><label><span>기준일</span><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label><span>전체 상태</span><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">전체</option><option value="정상">정상</option><option value="지각">지각</option><option value="출근 누락">출근 누락</option><option value="조퇴">조퇴</option></select></label><label><span>담당 직원</span><select value={staff} onChange={e=>setStaff(e.target.value)}><option value="all">전체</option>{attendanceRows.map(row=><option key={row.staff} value={row.staff}>{row.staff}</option>)}</select></label><label><span>제공 서비스</span><select value={service} onChange={e=>setService(e.target.value)}><option value="all">전체</option><option value="방문요양">방문요양</option><option value="행정지원">행정지원</option></select></label><Button onClick={reset}>초기화</Button></Card><Card><SectionTitle title="기간별 근태 기록" action={<strong className="teal-text">총 {filtered.length}건</strong>}/><div className="table"><div className="tr attendance-grid th"><span>직원</span><span>예정 출근</span><span>실제 출근</span><span>예정 퇴근</span><span>실제 퇴근</span><span>근무시간</span><span>상태</span><span/></div>{filtered.map(row=><button className="tr attendance-grid" key={row.staff} onClick={()=>open({title:`${row.staff} 근태 상세`,tag:row.status,tone:row.tone})}><span>{row.staff}</span><span>{row.scheduledIn}</span><span>{row.actualIn}</span><span>{row.scheduledOut}</span><span>{row.actualOut}</span><span>{row.hours}</span><Badge tone={row.tone}>{row.status}</Badge><Icon name="chev"/></button>)}{!filtered.length&&<p className="empty-filter-results">선택한 조건에 해당하는 근태 기록이 없습니다.</p>}</div></Card></Page>
}

function Matching({open}){return <Page><MetricStrip items={[{label:'매칭 요청',value:'4건',desc:'신규 2 · 변경 2'},{label:'확인 필요',value:'2건',desc:'이번 주 시작',tone:'red'},{label:'인수인계 중',value:'1건',desc:'첫 방문 전',tone:'orange'},{label:'이번 달 완료',value:'7건',desc:'평균 2.3일',tone:'green'}]}/><div className="two-col"><Card><SectionTitle title="배정이 필요한 수급자"/><Issue tone="danger" tag="신규 배정" title="정○○ 어르신" text="오전 방문 · 이동지원 경험 · 강서구" action={()=>open({title:'정○○ 매칭 요청',tag:'신규 배정',tone:'danger'})}/><Issue tone="warning" tag="담당 변경" title="홍○○ 어르신" text="목욕 지원 경험 · 인수인계 필요" action={()=>open({title:'홍○○ 담당자 변경',tag:'담당 변경',tone:'warning'})}/></Card><Card><SectionTitle title="추천 직원"/><Candidate name="김○○" score="조건 4/4 일치" text="가능 시간 일치 · 이동 12분 · 목욕 지원 경험"/><Candidate name="박○○" score="조건 3/4 일치" text="가능 시간 일치 · 이동 18분 · 담당 6명"/><Candidate name="최○○" score="조건 3/4 일치" text="이동 8분 · 선호 요일 조정 필요"/></Card></div><Card className="assignment-review"><SectionTitle title="정○○ 배정 검토" desc="추천 조건과 현재 업무량을 함께 확인한 뒤 담당자를 결정합니다."/><div className="detail-grid"><div><small>추천 직원</small><strong>김○○</strong></div><div><small>조건 일치</small><strong>4/4</strong></div><div className="assignment-date"><span><small>첫 방문 예정</small><strong>09.30 오전</strong></span><Button tone="primary" onClick={()=>open({title:'정○○ 배정',tag:'직원 매칭'})}>배정 하기</Button></div></div></Card><Card><SectionTitle title="담당자 변경·인수인계"/><div className="handover"><div><Badge tone="warning">확인 중</Badge><h3>홍○○ · 김○○ → 박○○</h3><p>돌봄 목표, 선호, 주의사항, 최근 개선 활동을 전달합니다.</p></div><Checklist items={['개인별 계획 확인','최근 돌봄 기록 확인','목욕 전 불안 대응 방법 확인','보호자 요청 확인','첫 방문 후 결과 등록']}/></div><div className="left-actions"><Button tone="primary" onClick={()=>open({title:'인수인계 상세',tag:'연속성 확인'})}>인수인계 확인</Button></div></Card></Page>}

function Candidate({name,score,text}){return <div className="candidate"><div><strong>{name}</strong><p>{text}</p></div><Badge tone="teal">{score}</Badge><Button>선택</Button></div>}

function Support({open}){return <Page><MetricStrip items={[{label:'신규 접수',value:'3건',desc:'미확인 1건',tone:'red'},{label:'조치 중',value:'5건',desc:'직원 확인 대기 2건',tone:'orange'},{label:'평균 처리기간',value:'2.4일',desc:'최근 3개월'},{label:'지원 만족도',value:'4.5/5',desc:'완료 후 응답',tone:'green'}]}/><Filters/><div className="two-col wide-left"><Card><SectionTitle title="직원 지원 요청" action={<Button tone="primary">요청 등록</Button>}/><Issue tone="danger" tag="건강·안전" title="오후 일정 조정 요청" text="박○○ · 근무 중 허리 불편 · 영향 일정 2건" action={()=>open({title:'직원 지원 상세',tag:'건강·안전',tone:'danger'})}/><Issue tone="warning" tag="업무 부담" title="연속 근무일 조정 요청" text="최○○ · 연속 6일 근무 · 담당자 확인 완료" action={()=>open({title:'업무 부담 지원',tag:'조치 중',tone:'warning'})}/><Issue tone="blue" tag="복리후생" title="건강검진 지원 신청" text="김○○ · 증빙 제출 완료 · 승인 대기" action={()=>open({title:'복리후생 신청 상세',tag:'승인 대기',tone:'blue'})}/></Card><Card><SectionTitle title="처리 현황"/><div className="status-list">{[['신규 접수',3],['확인 완료',2],['조치 중',5],['직원 확인 대기',2],['완료',14]].map(x=><div key={x[0]}><span>{x[0]}</span><strong>{x[1]}건</strong><Progress value={x[1]*7}/></div>)}</div></Card></div></Page>}

function Education({open}){
  const[tab,setTab]=useState('courses');
  const courseRows=[['노인인권 및 학대예방','필수','4명','09.30','3명 이수','해당 없음'],['목욕 전 불안 대응','추천','김○○','09.27','배정 대기','예정'],['낙상·미끄러짐 예방','안전','2명','10.05','수강 중','대기']];
  const peopleRows=[['김○○','2/2 이수','목욕 전 불안 대응','09.27','배정 대기','예정'],['박○○','1/2 이수','낙상·미끄러짐 예방','09.30','수강 중','대기'],['최○○','2/2 이수','해당 없음','—','완료','확인 완료']];
  const rows=tab==='courses'?courseRows:peopleRows;
  const headers=tab==='courses'?['교육','구분','대상','기한','진행 상태','적용 확인']:['직원','필수교육','추천교육','기한','진행 상태','적용 확인'];
  return <Page><MetricStrip items={[{label:'필수교육 이수율',value:'92%',desc:'대상 12명'},{label:'기한 초과',value:'1명',desc:'우선 확인',tone:'red'},{label:'추천교육 대기',value:'2건',desc:'기록 근거',tone:'orange'},{label:'적용 확인 대기',value:'3건',desc:'현장 기록 필요',tone:'blue'}]}/><div className="subtabs"><button className={tab==='courses'?'active':''} onClick={()=>setTab('courses')}>교육 과정</button><button className={tab==='people'?'active':''} onClick={()=>setTab('people')}>직원별 현황</button><button className={tab==='effect'?'active':''} onClick={()=>setTab('effect')}>교육 적용·효과</button></div>{tab!=='effect'?<Card><SectionTitle title={tab==='courses'?'교육 목록':'직원별 교육 현황'} action={<Button tone="primary">교육 배정</Button>}/><div className="table"><div className="tr education-grid th">{headers.map(x=><span key={x}>{x}</span>)}<span/></div>{rows.map(r=><button className="tr education-grid" key={r[0]} onClick={()=>open({title:`${r[0]} 교육 상세`,tag:r[1]})}>{r.map((x,index)=><span key={`${x}-${index}`}>{x}</span>)}<Icon name="chev"/></button>)}</div></Card>:<div className="two-col wide-left"><Card><SectionTitle title="적용 과제"/><Issue tone="warning" tag="적용 중" title="목욕 시작 전 순서 설명" text="김○○ · 대상 홍○○ · 적용 기간 09.20–10.04" action={()=>open({title:'교육 적용 과제',tag:'적용 중',tone:'warning'})}/><div className="six-steps"><div><strong>교육</strong><p>목욕 전 불안 대응 · 09.19 이수</p></div><div><strong>적용할 행동</strong><p>순서를 설명하고 물 온도를 직접 확인하도록 선택권 제공</p></div><div><strong>관련 기록</strong><p>09.20 · 09.22 · 09.24 방문 기록 3건</p></div></div></Card><Card className="education-effect"><SectionTitle title="적용 전후 변화"/><div className="compare"><div><small>적용 전</small><strong>거부 3/4회</strong></div><Icon name="arrow"/><div><small>적용 후</small><strong>거부 1/3회</strong></div></div><p>긍정적인 변화가 관찰됐지만 충분한 근거를 위해 2회 더 확인합니다.</p><div className="left-actions"><Button tone="primary">관리자 판단 등록</Button></div></Card></div>}</Page>
}

